plugins {
    id("orrery.android-library")
    id("orrery.publish")
    alias(libs.plugins.roborazzi)
    alias(libs.plugins.baselineprofile)
}

android {
    namespace = "me.kozakov.orrery.compose"
    resourcePrefix = "orrery_"
}

roborazzi {
    outputDir.set(file("src/test/snapshots"))
}

// Generated by :baselineprofile against the sample app; shipped in the AAR.
// Regenerate with ./gradlew :orrery-compose:generateBaselineProfile.
baselineProfile {
    filter {
        include("me.kozakov.orrery.**")
        exclude("me.kozakov.orrery.sample.**")
        exclude("me.kozakov.orrery.lunar.**")
    }
}

dependencies {
    api(project(":orrery-core"))
    baselineProfile(project(":baselineprofile"))
    implementation(platform(libs.compose.bom))
    implementation(libs.compose.foundation)
    implementation(libs.compose.material3)

    testImplementation(libs.junit4)
    testImplementation(libs.robolectric)
    testImplementation(libs.androidx.test.ext.junit)
    testImplementation(platform(libs.compose.bom))
    testImplementation(libs.compose.ui.test.junit4)
    testImplementation(libs.roborazzi)
    testImplementation(libs.roborazzi.compose)
    debugImplementation(platform(libs.compose.bom))
    debugImplementation(libs.compose.ui.test.manifest)
}
